//! Swift bindings for the mnemis engine, generated by uniffi.
//!
//! The iOS app holds one [`Engine`] over a database in its own container.
//! Everything that has to be correct — ingest, extraction, the LLM loop, sync —
//! stays in the engine; this crate only adapts it to uniffi: the DTOs from
//! `mnemis-types` are exported as remote records, errors flatten to a message,
//! and every call runs on a runtime this crate owns.

use std::future::Future;
use std::path::PathBuf;
use std::sync::{Arc, LazyLock, Once, RwLock};
use std::time::Duration;

use mnemis_engine::embed::{Embedder, NoEmbedder};
use mnemis_engine::llm::LlmBackend;
use mnemis_engine::source::SourceId;
use mnemis_engine::{config, db, mutations, orchestrator, queries, settings};
use mnemis_types::{
    ActionDto, ActionStatus, ChannelRowDto, Confidence, LlmConfigDto, LlmProvider,
    MessageActionRef, MessageDetailDto, ProfileIdentifier, SourceHealth, SourceRowDto,
    SourceStatus, StatusSnapshot, SyncOutcome, ThinkingLevel, UserProfileDto,
};
use sqlx::SqlitePool;

uniffi::setup_scaffolding!();

/// Every engine call runs here. The engine needs a tokio context (sqlx,
/// reqwest, the IMAP client); Swift's executor isn't one, so each exported
/// future is spawned onto this runtime and Swift awaits the join handle.
static RUNTIME: LazyLock<tokio::runtime::Runtime> = LazyLock::new(|| {
    tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .thread_name("mnemis-engine")
        .build()
        .expect("building the engine runtime")
});

async fn run<T, F>(fut: F) -> Result<T, MnemisError>
where
    T: Send + 'static,
    F: Future<Output = anyhow::Result<T>> + Send + 'static,
{
    match RUNTIME.spawn(fut).await {
        Ok(result) => result.map_err(MnemisError::from),
        Err(e) => Err(MnemisError::Failed {
            message: format!("engine task failed: {e}"),
        }),
    }
}

#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum MnemisError {
    #[error("{message}")]
    Failed { message: String },
}

impl From<anyhow::Error> for MnemisError {
    fn from(e: anyhow::Error) -> Self {
        MnemisError::Failed {
            message: format!("{e:#}"),
        }
    }
}

/// The configured LLM, rebuilt whenever its config is saved.
struct LlmStack {
    llm: LlmBackend,
    chat_model: String,
    window_char_budget: usize,
    idle_timeout: Duration,
}

impl LlmStack {
    async fn build(cfg: &config::Config) -> anyhow::Result<Self> {
        Ok(LlmStack {
            llm: LlmBackend::from_config(&cfg.llm).await?,
            chat_model: cfg.llm.chat_model.clone(),
            window_char_budget: mnemis_engine::extract::window_char_budget_for(
                cfg.llm.resolved_max_context_tokens(),
            ),
            idle_timeout: Duration::from_secs(cfg.llm.resolved_chat_idle_timeout_secs()),
        })
    }
}

#[derive(uniffi::Object)]
pub struct Engine {
    pool: SqlitePool,
    data_dir: PathBuf,
    llm: RwLock<Option<Arc<LlmStack>>>,
}

impl Engine {
    fn config_path(&self) -> PathBuf {
        self.data_dir.join("config.toml")
    }

    fn current_llm(&self) -> Option<Arc<LlmStack>> {
        self.llm.read().ok().and_then(|g| g.clone())
    }

    fn set_llm(&self, stack: Option<Arc<LlmStack>>) {
        if let Ok(mut g) = self.llm.write() {
            *g = stack;
        }
    }
}

#[uniffi::export]
impl Engine {
    /// Open (creating if needed) the database and config under `data_dir`,
    /// the app's Application Support directory.
    #[uniffi::constructor]
    pub async fn open(data_dir: String) -> Result<Arc<Self>, MnemisError> {
        init_logging();
        let data_dir = PathBuf::from(data_dir);
        run(async move {
            std::fs::create_dir_all(&data_dir)?;
            let pool = db::open(&data_dir.join("mnemis.db")).await?;
            db::migrate(&pool).await?;
            // A missing or unusable LLM config leaves the app usable read-only;
            // only sync needs it.
            let llm = match config::load(Some(&data_dir.join("config.toml"))) {
                Ok(cfg) => match LlmStack::build(&cfg).await {
                    Ok(stack) => Some(Arc::new(stack)),
                    Err(e) => {
                        tracing::warn!(error = %format!("{e:#}"), "LLM not usable");
                        None
                    }
                },
                Err(_) => None,
            };
            Ok(Arc::new(Engine {
                pool,
                data_dir,
                llm: RwLock::new(llm),
            }))
        })
        .await
    }

    pub async fn list_actions(
        &self,
        include_resolved: bool,
    ) -> Result<Vec<ActionDto>, MnemisError> {
        let pool = self.pool.clone();
        run(async move {
            queries::list_actions(&pool, queries::ActionFilter { include_resolved }).await
        })
        .await
    }

    pub async fn get_message(&self, message_id: i64) -> Result<MessageDetailDto, MnemisError> {
        let pool = self.pool.clone();
        run(async move { queries::get_message(&pool, message_id).await }).await
    }

    pub async fn set_action_status(
        &self,
        action_id: i64,
        status: ActionStatus,
        dismissed_reason: Option<String>,
    ) -> Result<(), MnemisError> {
        let pool = self.pool.clone();
        run(async move {
            mutations::update_action_status(&pool, action_id, status, dismissed_reason).await
        })
        .await
    }

    pub async fn status(&self) -> Result<StatusSnapshot, MnemisError> {
        let pool = self.pool.clone();
        run(async move { queries::get_status(&pool).await }).await
    }

    pub async fn list_sources(&self) -> Result<Vec<SourceRowDto>, MnemisError> {
        let pool = self.pool.clone();
        run(async move { settings::list_sources(&pool).await }).await
    }

    /// Add an IMAP account; the password goes to the Keychain, not the database.
    pub async fn add_imap_source(
        &self,
        name: String,
        server: String,
        port: u16,
        username: String,
        password: String,
    ) -> Result<i64, MnemisError> {
        let pool = self.pool.clone();
        run(async move {
            settings::add_imap_source(&pool, &name, &server, port, &username, &password).await
        })
        .await
    }

    pub async fn delete_source(&self, source_id: i64) -> Result<(), MnemisError> {
        let pool = self.pool.clone();
        run(async move { settings::delete_source(&pool, source_id).await }).await
    }

    /// The source's folders, refreshed from the server first so ones created
    /// there show up. Discovery is best-effort: offline, the known folders
    /// still come back.
    pub async fn list_folders(&self, source_id: i64) -> Result<Vec<ChannelRowDto>, MnemisError> {
        let pool = self.pool.clone();
        run(async move {
            match orchestrator::build_imap_source(&pool, SourceId(source_id)).await {
                Ok(source) => {
                    if let Err(e) = orchestrator::discover_channels(&pool, &source, source_id).await
                    {
                        tracing::warn!(error = %format!("{e:#}"), source_id, "folder discovery failed");
                    }
                }
                Err(e) => {
                    tracing::warn!(error = %format!("{e:#}"), source_id, "no source for discovery")
                }
            }
            settings::list_source_channels(&pool, source_id).await
        })
        .await
    }

    /// Subscribe to (poll) or mute a folder.
    pub async fn set_folder_subscribed(
        &self,
        channel_id: i64,
        subscribed: bool,
    ) -> Result<(), MnemisError> {
        let pool = self.pool.clone();
        run(async move { settings::set_channel_muted(&pool, channel_id, !subscribed).await }).await
    }

    pub async fn user_profile(&self) -> Result<UserProfileDto, MnemisError> {
        let pool = self.pool.clone();
        run(async move { settings::get_user_profile(&pool).await }).await
    }

    pub async fn save_user_profile(&self, profile: UserProfileDto) -> Result<(), MnemisError> {
        let pool = self.pool.clone();
        run(async move { settings::save_user_profile(&pool, &profile).await }).await
    }

    /// The LLM config, or defaults when none is saved. The API key never comes
    /// back; `anthropic_api_key_set` says whether one is stored.
    pub async fn llm_config(&self) -> Result<LlmConfigDto, MnemisError> {
        let path = self.config_path();
        run(async move {
            let key_set = mnemis_engine::llm::anthropic_api_key().await.is_some();
            let config_path = path.display().to_string();
            Ok(match config::load(Some(&path)) {
                Ok(cfg) => LlmConfigDto {
                    thinking_level: cfg.llm.resolved_thinking_level(),
                    provider: cfg.llm.provider,
                    base_url: cfg.llm.base_url,
                    chat_model: cfg.llm.chat_model,
                    bearer_token: cfg.llm.bearer_token,
                    anthropic_api_key: None,
                    anthropic_api_key_set: key_set,
                    config_path,
                },
                Err(_) => LlmConfigDto {
                    anthropic_api_key_set: key_set,
                    config_path,
                    ..Default::default()
                },
            })
        })
        .await
    }

    /// Save the LLM config (and a new API key, when given) and rebuild the
    /// live LLM so the next sync uses it.
    pub async fn save_llm_config(self: Arc<Self>, cfg: LlmConfigDto) -> Result<(), MnemisError> {
        let engine = Arc::clone(&self);
        run(async move {
            if let Some(key) = cfg.anthropic_api_key.as_deref().map(str::trim)
                && !key.is_empty()
            {
                mnemis_engine::secrets::store(mnemis_engine::anthropic::API_KEY_REF, key).await?;
            }
            let path = engine.config_path();
            config::save_llm_at(
                &path,
                &config::LlmSection {
                    provider: cfg.provider,
                    base_url: cfg.base_url,
                    chat_model: cfg.chat_model,
                    bearer_token: cfg.bearer_token.filter(|s| !s.trim().is_empty()),
                    max_context_tokens: None,
                    request_timeout_secs: None,
                    chat_idle_timeout_secs: None,
                    thinking_level: Some(cfg.thinking_level),
                },
            )?;
            match LlmStack::build(&config::load(Some(&path))?).await {
                Ok(stack) => {
                    engine.set_llm(Some(Arc::new(stack)));
                    Ok(())
                }
                Err(e) => {
                    engine.set_llm(None);
                    Err(e.context("saved, but the LLM isn't usable yet"))
                }
            }
        })
        .await
    }

    /// Poll every source, extract actions, and sync the calendar.
    pub async fn sync_now(&self) -> Result<SyncOutcome, MnemisError> {
        let stack = self.current_llm().ok_or_else(|| MnemisError::Failed {
            message: "No LLM configured. Set it up in Settings.".into(),
        })?;
        let pool = self.pool.clone();
        let traces = config::traces_dir_for(&self.data_dir.join("mnemis.db"));
        run(async move {
            let embedder: Arc<dyn Embedder> = Arc::new(NoEmbedder);
            orchestrator::sync_now(
                &pool,
                &stack.llm,
                embedder,
                &stack.chat_model,
                stack.window_char_budget,
                stack.idle_timeout,
                Some(&traces),
            )
            .await
        })
        .await
    }
}

fn init_logging() {
    static ONCE: Once = Once::new();
    ONCE.call_once(|| {
        let _ = tracing_subscriber::fmt()
            .with_env_filter(
                tracing_subscriber::EnvFilter::try_from_default_env()
                    .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
            )
            .with_ansi(false)
            .try_init();
    });
}

// The wire types live in `mnemis-types`, shared with the desktop frontend;
// these mirror their definitions so uniffi can export them as they are.

#[uniffi::remote(Enum)]
pub enum Confidence {
    Low,
    Medium,
    High,
}

#[uniffi::remote(Enum)]
pub enum ActionStatus {
    Pending,
    AutoClaimed,
    Claimed,
    Done,
    Cancelled,
    Dismissed,
}

#[uniffi::remote(Enum)]
pub enum SourceHealth {
    Ok,
    Warning,
    Failed,
    Disabled,
}

#[uniffi::remote(Enum)]
pub enum ThinkingLevel {
    Low,
    Medium,
    High,
    ExtraHigh,
}

#[uniffi::remote(Enum)]
pub enum LlmProvider {
    OpenaiResponses,
    Anthropic,
}

#[uniffi::remote(Record)]
pub struct ActionDto {
    pub id: i64,
    pub title: String,
    pub details: Option<String>,
    pub confidence: Confidence,
    pub status: ActionStatus,
    pub created_at: i64,
    pub due_at: Option<i64>,
    pub source_posted_at: Option<i64>,
    pub source_message_id: Option<i64>,
    pub evidence_count: i64,
    pub channel_name: Option<String>,
    pub source_name: Option<String>,
    pub sync_status: Option<String>,
}

#[uniffi::remote(Record)]
pub struct MessageActionRef {
    pub id: i64,
    pub title: String,
    pub confidence: Confidence,
    pub status: ActionStatus,
    pub due_at: Option<i64>,
}

#[uniffi::remote(Record)]
pub struct MessageDetailDto {
    pub id: i64,
    pub subject: Option<String>,
    pub body: String,
    pub body_format: String,
    pub author_display: Option<String>,
    pub author_addr: Option<String>,
    pub posted_at: i64,
    pub channel_name: Option<String>,
    pub source_name: Option<String>,
    pub actions: Vec<MessageActionRef>,
}

#[uniffi::remote(Record)]
pub struct SourceStatus {
    pub id: i64,
    pub name: String,
    pub kind: String,
    pub health: SourceHealth,
    pub last_synced_at: Option<i64>,
    pub last_error: Option<String>,
    pub consecutive_failures: i64,
}

#[uniffi::remote(Record)]
pub struct StatusSnapshot {
    pub sources: Vec<SourceStatus>,
    pub embed_queue_depth: i64,
    pub last_extraction_at: Option<i64>,
}

#[uniffi::remote(Record)]
pub struct SyncOutcome {
    pub sources_synced: i64,
    pub sources_failed: i64,
    pub channels_polled: i64,
    pub messages_ingested: i64,
    pub embeddings_drained: i64,
    pub actions_created: i64,
    pub errors: Vec<String>,
}

#[uniffi::remote(Record)]
pub struct SourceRowDto {
    pub id: i64,
    pub name: String,
    pub kind: String,
    pub muted: bool,
    pub health: SourceHealth,
    pub last_synced_at: Option<i64>,
    pub last_error: Option<String>,
}

#[uniffi::remote(Record)]
pub struct ChannelRowDto {
    pub id: i64,
    pub source_id: i64,
    pub external_id: String,
    pub name: String,
    pub kind: String,
    pub muted: bool,
    pub last_synced_at: Option<i64>,
    pub message_count: i64,
}

#[uniffi::remote(Record)]
pub struct ProfileIdentifier {
    pub kind: String,
    pub value: String,
}

#[uniffi::remote(Record)]
pub struct UserProfileDto {
    pub display_name: String,
    pub custom_prompt: Option<String>,
    pub identifiers: Vec<ProfileIdentifier>,
}

#[uniffi::remote(Record)]
pub struct LlmConfigDto {
    pub provider: LlmProvider,
    pub base_url: String,
    pub chat_model: String,
    pub bearer_token: Option<String>,
    pub thinking_level: ThinkingLevel,
    pub anthropic_api_key: Option<String>,
    pub anthropic_api_key_set: bool,
    pub config_path: String,
}
